def sedimentation_rate(thickness_m, duration_my):
    if duration_my <= 0.0:
        return 0.0
    return thickness_m / duration_my



def age_from_depth(depth_m, surface_age_ma, sed_rate):
    if sed_rate <= 0.0:
        return surface_age_ma
    return surface_age_ma + depth_m / sed_rate



def radiometric_age(parent_to_daughter_ratio, decay_constant):
    if decay_constant <= 0.0 or parent_to_daughter_ratio < 0.0:
        return 0.0
    return math.log(1.0 + parent_to_daughter_ratio) / decay_constant



def radiocarbon_age(activity_fraction):
    if activity_fraction <= 0.0 or activity_fraction > 1.0:
        return 0.0
    return -8267.0 * math.log(activity_fraction)



def stratigraphic_column_depth(layer_thickness1, layer_thickness2, n_layers):
    return (layer_thickness1 + layer_thickness2) * n_layers / 2.0



def isotope_fractionation(sample_ratio, standard_ratio):
    if standard_ratio <= 0.0:
        return 0.0
    return (sample_ratio / standard_ratio - 1.0) * 1000.0



def unconformity_gap(section_above_age, section_below_age):
    gap = section_below_age - section_above_age
    if gap < 0.0:
        return 0.0
    return gap



def thermal_maturity_vitrinite(max_temperature, duration_my):

    ro = math.exp(0.0078 * max_temperature - 1.2) * (1.0 + 0.01 * math.log(duration_my + 1.0))
    if ro < 0.2:
        return 0.2
    return ro



def compaction_correction(observed_thickness, initial_porosity, current_porosity):
    denom = 1.0 - initial_porosity
    if denom <= 0.0:
        return observed_thickness
    return observed_thickness * (1.0 - current_porosity) / denom



def sea_level_proxy(d18o_benthic, d18o_reference, ice_volume_factor):
    return -ice_volume_factor * (d18o_benthic - d18o_reference)
